<script setup>
import { computed, onMounted, ref } from 'vue'
import { apiOrigin, canAccess } from '../services/auth.js'
import DeskTabs from './DeskTabs.vue'
import PriceApprovalPanel from './PriceApprovalPanel.vue'
const props = defineProps({ session: { type: Object, required: true } })
const emit = defineEmits(['navigate'])
const bucket = ref('soon'), data = ref(null), page = ref(0), busy = ref(false), error = ref(''), selected = ref(null), locked = ref(false)
const tabs = computed(() => [{ id: 'soon', label: `Найближчі дати (${data.value?.counts.soon ?? '—'})` }, { id: 'attention', label: `Потребують уваги (${data.value?.counts.attention ?? '—'})` }, { id: 'pickup', label: `На філії до видачі (${data.value?.counts.pickup ?? '—'})` }])
const yes = v => v === true || Number(v) === 1
const states = { WAITING: 'Нове', ACCEPTED: 'Прийнято майстром', IN_PROGRESS: 'У роботі', COMPLETED: 'Виготовлено', STOPPED: 'Зупинено' }
async function load(next = 0) { if (busy.value || locked.value) return; busy.value = true; error.value = ''; data.value = null; page.value = next; try { const r = await fetch(`${apiOrigin}/api/tasks/deadlines?bucket=${bucket.value}&page=${next}`, { headers: { Authorization: `Bearer ${props.session.token}` }, cache: 'no-store' }); const result = await r.json(); if (!r.ok) throw new Error(result.message || 'Не вдалося завантажити строки'); data.value = result } catch (e) { error.value = e.message } finally { busy.value = false } }
function choose(value) { if (busy.value || locked.value) return; bucket.value = value; selected.value = null; load() }
function customer(row) { emit('navigate', { section: 'customers', customer: { ...row, company: row.customerName, mobile: row.phone } }) }
onMounted(load)
</script>
<template><section class="deadline-tasks"><header><div><h2>Строки та видача</h2><p>Кількість виробів. Один виріб може бути в кількох списках.</p></div><button :disabled="busy || locked" @click="load(page)">Оновити строки</button></header><DeskTabs :tabs="tabs" :model-value="bucket" label="Контроль строків" @update:model-value="choose" /><p v-if="error" role="alert">{{ error }}</p><p v-if="busy">Завантаження…</p><template v-if="data"><p v-if="bucket === 'soon'">Готовність від {{ data.today }} до {{ data.horizon }}: сьогодні та {{ data.upcomingDays }} наступних робочих днів.</p><p v-if="bucket === 'attention'">Строк минув, є дефіцит або потрібно погодження ціни. Це поточні ознаки; точну причину затримки слід уточнити в майстерні.</p><p v-if="bucket === 'pickup'">Лише готові вироби, прийняті на філію й доступні до видачі. Очікування — календарні дні від останнього приймання.</p><p v-if="!data.rows.length">За цими умовами виробів немає.</p><article v-for="r in data.rows" :key="r.productId"><h3>Замовлення №{{ r.orderNo }} · {{ r.productName }}</h3><p>{{ r.customerName }} · {{ r.phone }} · {{ r.branchName }}</p><p>Готовність: {{ r.dueDate || 'Не вказано' }} · {{ states[r.state] || r.state }}</p><p v-if="bucket === 'pickup'"><strong>{{ r.waitingDays == null ? 'Дата приймання не зафіксована' : `На філії: ${r.waitingDays} дн.` }}</strong></p><template v-else><p v-if="r.dueDate && r.dueDate < data.today" class="warning">Погоджена дата готовності минула.</p><p v-if="yes(r.shortage)" class="warning">Є дефіцит матеріалів.</p><p v-if="yes(r.needsApproval)" class="warning">Потрібне погодження ціни.</p></template><div class="actions"><button v-if="canAccess(session, 'workshop:read')" :disabled="busy || locked" @click="emit('navigate', { section: 'workshop', orderNo: r.orderNo })">Картка в майстерні</button><button v-if="bucket === 'pickup' && canAccess(session, 'orders:read')" :disabled="busy || locked" @click="emit('navigate', { section: 'orders', orderNo: r.orderNo, tab: 'READY' })">Оплата та видача</button><button v-if="canAccess(session, 'customers:crm:read')" :disabled="busy || locked" @click="customer(r)">Клієнт та історія контактів</button><button v-if="yes(r.needsApproval) && canAccess(session, 'customers:crm:read')" :disabled="locked" @click="selected = r">Погодження ціни</button></div><section v-if="selected?.productId === r.productId"><PriceApprovalPanel :session="session" :product-id="Number(r.productId)" :revision="0" @busy="locked = $event" @changed="selected = null; load(page)" /></section></article><div class="actions"><button :disabled="busy || locked || !page" @click="load(page - 1)">Назад</button><span>Сторінка {{ page + 1 }}</span><button :disabled="busy || locked || !data.hasMore" @click="load(page + 1)">Далі</button></div></template></section></template>
<style scoped>.deadline-tasks{margin:20px 0;padding:16px;border:1px solid #d8e3e8;border-radius:12px;background:white;min-width:0}.deadline-tasks header{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.deadline-tasks article{padding:14px 0;border-bottom:1px solid #d8e3e8;overflow-wrap:anywhere}.actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:12px 0}.warning{color:#795413}.deadline-tasks button{min-height:44px}@media(max-width:600px){.deadline-tasks{padding:12px}.actions button{flex:1 1 160px}}</style>
